import React, { useEffect, useState } from 'react';
import { Table, Button, Form, Modal, Card, Badge, Row, Col } from 'react-bootstrap';
import api from '../services/api';
import { toast } from 'react-toastify';

const StaffList = () => {
  const [staff, setStaff] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [newStaff, setNewStaff] = useState({ name: '', email: '', temporaryPassword: '' });

  const fetchStaff = async () => {
    try {
      const { data } = await api.get('/admin/staff');
      setStaff(data);
    } catch (err) {
      toast.error('Failed to load staff list');
    }
  };

  useEffect(() => {
    fetchStaff();
  }, []);

  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      await api.post('/admin/staff', newStaff);
      toast.success('Staff account created!');
      setShowModal(false);
      setNewStaff({ name: '', email: '', temporaryPassword: '' });
      fetchStaff();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Error creating staff');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to remove this staff member?')) return;
    try {
      await api.delete(`/admin/staff/${id}`);
      toast.success('Staff member deleted');
      fetchStaff();
    } catch (err) {
      toast.error('Delete failed');
    }
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h3 className="fw-bold mb-1">Staff Management</h3>
          <p className="text-muted small mb-0">Create credentials & manage access for your team</p>
        </div>
        <Button className="btn-primary-gradient" onClick={() => setShowModal(true)}>
          + Add New Staff Member
        </Button>
      </div>

      <Row className="g-3 mb-4">
        <Col md={6} lg={4}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon primary">👥</div>
            <div>
              <div className="text-muted small fw-semibold">Total Staff Accounts</div>
              <h4 className="fw-bold mb-0">{staff.length} Active Staff</h4>
            </div>
          </div>
        </Col>
        <Col md={6} lg={4}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon success">🛡️</div>
            <div>
              <div className="text-muted small fw-semibold">Access Privilege</div>
              <h4 className="fw-bold mb-0">Role: Staff Access</h4>
            </div>
          </div>
        </Col>
      </Row>

      <Card className="p-4 border-0">
        <Table responsive className="custom-table mb-0">
          <thead>
            <tr>
              <th>Staff Member</th>
              <th>Email Address</th>
              <th>Role</th>
              <th>Status</th>
              <th className="text-end">Actions</th>
            </tr>
          </thead>
          <tbody>
            {staff.length === 0 ? (
              <tr>
                <td colSpan="5" className="text-center py-4 text-muted">
                  No staff members created yet. Click "+ Add New Staff Member" to grant access.
                </td>
              </tr>
            ) : (
              staff.map((s) => (
                <tr key={s._id}>
                  <td>
                    <div className="d-flex align-items-center gap-3">
                      <div 
                        className="d-flex align-items-center justify-content-center text-white fw-bold shadow-sm"
                        style={{
                          width: '40px',
                          height: '40px',
                          borderRadius: '12px',
                          background: 'linear-gradient(135deg, #4318ff 0%, #00c6ff 100%)'
                        }}
                      >
                        {s.name ? s.name.charAt(0).toUpperCase() : 'S'}
                      </div>
                      <div className="fw-semibold">{s.name}</div>
                    </div>
                  </td>
                  <td>{s.email}</td>
                  <td>
                    <Badge bg="primary" className="px-3 py-2 rounded-pill fw-semibold">
                      {s.role}
                    </Badge>
                  </td>
                  <td>
                    <span className="badge bg-success-subtle text-success px-3 py-2 rounded-pill">Active</span>
                  </td>
                  <td className="text-end">
                    <Button 
                      variant="outline-danger" 
                      size="sm" 
                      onClick={() => handleDelete(s._id)}
                      style={{ borderRadius: '8px' }}
                    >
                      Delete
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </Card>

      {/* Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} centered>
        <Modal.Header closeButton className="border-0 pb-0">
          <Modal.Title className="fw-bold">Create Staff Account</Modal.Title>
        </Modal.Header>
        <Modal.Body className="p-4">
          <Form onSubmit={handleCreate}>
            <Form.Group className="mb-3">
              <Form.Label className="small fw-semibold">Full Name</Form.Label>
              <Form.Control 
                required 
                value={newStaff.name} 
                onChange={e => setNewStaff({ ...newStaff, name: e.target.value })} 
                placeholder="e.g. John Doe"
                style={{ borderRadius: '10px' }}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label className="small fw-semibold">Email Address</Form.Label>
              <Form.Control 
                type="email" 
                required 
                value={newStaff.email} 
                onChange={e => setNewStaff({ ...newStaff, email: e.target.value })} 
                placeholder="john@company.com"
                style={{ borderRadius: '10px' }}
              />
            </Form.Group>
            <Form.Group className="mb-4">
              <Form.Label className="small fw-semibold">Assign Password</Form.Label>
              <Form.Control 
                required 
                type="password"
                value={newStaff.temporaryPassword} 
                onChange={e => setNewStaff({ ...newStaff, temporaryPassword: e.target.value })} 
                placeholder="Set initial password for staff"
                style={{ borderRadius: '10px' }}
              />
            </Form.Group>
            <div className="d-flex justify-content-end gap-2 pt-2">
              <Button variant="secondary" onClick={() => setShowModal(false)} style={{ borderRadius: '10px' }}>Cancel</Button>
              <Button className="btn-primary-gradient" type="submit">Create Credentials</Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>
    </div>
  );
};

export default StaffList;
